### Step 1.3: Implementation

#### `internal/gateway/middleware/cors.go`
```go
package middleware

import (
	"fmt"
	"net/http"
	"strings"
)

// CORSConfig defines configuration options for cross-origin requests.
type CORSConfig struct {
	// AllowedOrigins is an explicit list of authorized origins (e.g. "https://app.example.com").
	// Wildcards such as "*.example.com" are rejected to avoid subdomain takeover.
	AllowedOrigins   []string
	AllowedMethods   []string
	AllowedHeaders   []string
	ExposedHeaders   []string
	AllowCredentials bool
	MaxAgeSeconds    int
}

// NewCORS creates a CORS middleware with strict origin validation.
func NewCORS(cfg CORSConfig) func(http.Handler) http.Handler {
	allowedOriginMap := make(map[string]struct{}, len(cfg.AllowedOrigins))
	for _, o := range cfg.AllowedOrigins {
		trimmed := strings.TrimSpace(o)
		if strings.Contains(trimmed, "*") {
			panic(fmt.Sprintf("insecure wildcard in origin rejected: %q", trimmed))
		}
		allowedOriginMap[trimmed] = struct{}{}
	}

	methodsHeader := strings.Join(cfg.AllowedMethods, ", ")
	headersHeader := strings.Join(cfg.AllowedHeaders, ", ")
	exposedHeader := strings.Join(cfg.ExposedHeaders, ", ")
	maxAgeHeader := fmt.Sprintf("%d", cfg.MaxAgeSeconds)

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			origin := r.Header.Get("Origin")
			if origin == "" {
				next.ServeHTTP(w, r)
				return
			}

			_, allowed := allowedOriginMap[origin]
			isPreflight := r.Method == http.MethodOptions && r.Header.Get("Access-Control-Request-Method") != ""

			if !allowed {
				if isPreflight {
					w.WriteHeader(http.StatusForbidden)
					return
				}
				// Non-preflight: proceed without injecting CORS headers
				next.ServeHTTP(w, r)
				return
			}

			// Origin is strictly allowed
			w.Header().Set("Access-Control-Allow-Origin", origin)
			w.Header().Add("Vary", "Origin")

			if cfg.AllowCredentials {
				w.Header().Set("Access-Control-Allow-Credentials", "true")
			}

			if isPreflight {
				if methodsHeader != "" {
					w.Header().Set("Access-Control-Allow-Methods", methodsHeader)
				}
				if headersHeader != "" {
					w.Header().Set("Access-Control-Allow-Headers", headersHeader)
				}
				if cfg.MaxAgeSeconds > 0 {
					w.Header().Set("Access-Control-Max-Age", maxAgeHeader)
				}
				w.WriteHeader(http.StatusNoContent)
				return
			}

			if exposedHeader != "" {
				w.Header().Set("Access-Control-Expose-Headers", exposedHeader)
			}

			next.ServeHTTP(w, r)
		})
	}
}
```

