#### Step 2: Developer — gRPC Service Implementation

```go
// account_service.go
package main

import (
	"context"
	"errors"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	pb "account/v1"
)

type Account struct {
	ID     string
	Status string // "ACTIVE", "INACTIVE"
	Email  string
}

type AccountRepository interface {
	GetAccount(ctx context.Context, id string) (*Account, error)
	SaveAccount(ctx context.Context, acc *Account) error
}

type AccountServer struct {
	pb.UnimplementedAccountServiceServer
	repo AccountRepository
}

func NewAccountServer(repo AccountRepository) *AccountServer {
	return &AccountServer{repo: repo}
}

func (s *AccountServer) UpdateAccount(ctx context.Context, req *pb.UpdateAccountRequest) (*pb.AccountResponse, error) {
	if req.GetAccountId() == "" {
		return nil, status.Error(codes.InvalidArgument, "account_id is required")
	}

	acc, err := s.repo.GetAccount(ctx, req.GetAccountId())
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, status.Error(codes.NotFound, "account not found")
		}
		return nil, status.Errorf(codes.Internal, "failed to fetch account: %v", err)
	}

	// Partial Patch: Status presence evaluation
	if req.Status != nil {
		switch *req.Status {
		case pb.AccountStatus_ACCOUNT_STATUS_ACTIVE:
			acc.Status = "ACTIVE"
		case pb.AccountStatus_ACCOUNT_STATUS_INACTIVE:
			acc.Status = "INACTIVE"
		default:
			return nil, status.Error(codes.InvalidArgument, "invalid or unspecified account status")
		}
	}

	// Partial Patch: Email presence evaluation
	if req.Email != nil {
		acc.Email = *req.Email
	}

	if err := s.repo.SaveAccount(ctx, acc); err != nil {
		return nil, status.Errorf(codes.Internal, "failed to persist account: %v", err)
	}

	// Map domain back to proto response
	protoStatus := pb.AccountStatus_ACCOUNT_STATUS_UNSPECIFIED
	switch acc.Status {
	case "ACTIVE":
		protoStatus = pb.AccountStatus_ACCOUNT_STATUS_ACTIVE
	case "INACTIVE":
		protoStatus = pb.AccountStatus_ACCOUNT_STATUS_INACTIVE
	}

	return &pb.AccountResponse{
		AccountId: acc.ID,
		Status:    protoStatus,
		Email:     acc.Email,
	}, nil
}

var ErrNotFound = errors.New("not found")
```

