### B. Subgraph Resolvers (`src/inventory/resolvers.ts`)

```typescript
import { GraphQLResolveInfo } from 'graphql';

interface ProductEntityKey {
  __typename: 'Product';
  id: string;
}

interface InventoryRecord {
  productId: string;
  unitPrice: number; // Stored in inventory DB
  stockCount: number;
}

export interface InventoryDataSource {
  getInventoryByProductId(id: string): Promise<InventoryRecord | null>;
}

export interface Context {
  dataSources: {
    inventoryApi: InventoryDataSource;
  };
}

export const resolvers = {
  Product: {
    // Entity Reference Resolver for Apollo Federation Gateway query plans
    __resolveReference: async (
      reference: ProductEntityKey,
      context: Context
    ) => {
      const record = await context.dataSources.inventoryApi.getInventoryByProductId(reference.id);
      if (!record) {
        throw new Error(`Inventory record not found for product ID: ${reference.id}`);
      }
      return {
        id: reference.id,
        price: record.unitPrice,
        quantityOnHand: record.stockCount,
      };
    },

    // Explicit field resolvers
    price: (parent: { price?: number }) => {
      if (parent.price === undefined) {
        throw new Error('Price could not be resolved from inventory context.');
      }
      return parent.price;
    },

    quantityOnHand: (parent: { quantityOnHand: number }) => {
      return parent.quantityOnHand;
    },
  },
};
```

