### 4.2 Middleware Implementation
`src/middleware/authV2.ts`

```typescript
import { Request, Response, NextFunction } from 'express';

export interface TokenClaims {
  sub: string;
  tenantId: string;
  scopes: string[];
  [key: string]: unknown;
}

export interface TokenValidator {
  validate(token: string): Promise<TokenClaims>;
}

export function authV2Middleware(validator: TokenValidator) {
  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    // 1. Explicitly reject deprecated X-API-Key header
    if (req.headers['x-api-key']) {
      res.setHeader('WWW-Authenticate', 'Bearer error="invalid_token"');
      res.status(401).json({
        error: 'Unauthorized',
        code: 'LEGACY_AUTH_NOT_SUPPORTED',
        message: 'X-API-Key authentication is removed in API v2. Use OAuth2 Bearer tokens.',
      });
      return;
    }

    // 2. Extract Authorization header
    const authHeader = req.headers['authorization'];
    if (!authHeader) {
      res.setHeader(
        'WWW-Authenticate',
        'Bearer error="invalid_request", error_description="Missing Authorization header"'
      );
      res.status(401).json({
        error: 'Unauthorized',
        code: 'MISSING_AUTHORIZATION_HEADER',
        message: 'Authorization header is required.',
      });
      return;
    }

    // 3. Verify Bearer scheme
    const bearerMatch = authHeader.match(/^Bearer\s+([A-Za-z0-9\-._~+/]+=*)$/);
    if (!bearerMatch) {
      res.setHeader(
        'WWW-Authenticate',
        'Bearer error="invalid_token", error_description="Malformed or non-Bearer token"'
      );
      res.status(401).json({
        error: 'Unauthorized',
        code: 'INVALID_AUTH_SCHEME',
        message: 'Expected Bearer token format: Authorization: Bearer <token>',
      });
      return;
    }

    const token = bearerMatch[1];

    // 4. Validate Token & Claims
    try {
      const claims = await validator.validate(token);
      (req as any).user = claims;
      next();
    } catch (err: unknown) {
      res.setHeader(
        'WWW-Authenticate',
        'Bearer error="invalid_token", error_description="The token is expired or invalid"'
      );
      res.status(401).json({
        error: 'Unauthorized',
        code: 'INVALID_TOKEN',
        message: 'Provided access token is invalid or expired.',
      });
    }
  };
}
```

