### 3.1 CORS Middleware (`src/middleware/cors.ts`)
```typescript
import { Request, Response, NextFunction } from 'express';

export interface CorsConfig {
  allowedOrigins: string[];
  allowedMethods: string[];
  allowedHeaders: string[];
  allowCredentials?: boolean;
  maxAge?: number;
}

const EXPOSED_HEADERS = [
  'RateLimit-Limit',
  'RateLimit-Remaining',
  'RateLimit-Reset',
  'Retry-After',
].join(', ');

export function createCorsMiddleware(config: CorsConfig) {
  const allowedSet = new Set(config.allowedOrigins);

  return (req: Request, res: Response, next: NextFunction): void => {
    const origin = req.headers.origin;

    if (!origin) {
      return next();
    }

    // Exact FQDN whitelist check
    const isAllowed = allowedSet.has(origin);

    if (!isAllowed) {
      if (req.method === 'OPTIONS') {
        res.status(403).end();
        return;
      }
      return next();
    }

    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Vary', 'Origin');
    res.setHeader('Access-Control-Expose-Headers', EXPOSED_HEADERS);

    if (config.allowCredentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    if (req.method === 'OPTIONS') {
      res.setHeader('Access-Control-Allow-Methods', config.allowedMethods.join(', '));
      res.setHeader('Access-Control-Allow-Headers', config.allowedHeaders.join(', '));
      if (config.maxAge) {
        res.setHeader('Access-Control-Max-Age', config.maxAge.toString());
      }
      res.status(204).end();
      return;
    }

    next();
  };
}
```

### 3.2 Rate-Limiter Middleware (`src/middleware/rateLimiter.ts`)
```typescript
import { Request, Response, NextFunction } from 'express';

export interface RateLimitConfig {
  windowMs: number;
  max: number;
}

interface Bucket {
  count: number;
  resetTime: number;
}

export function createRateLimiter(config: RateLimitConfig) {
  const store = new Map<string, Bucket>();

  return (req: Request, res: Response, next: NextFunction): void => {
    const key = req.ip || req.socket.remoteAddress || 'unknown';
    const now = Date.now();

    let bucket = store.get(key);
    if (!bucket || now >= bucket.resetTime) {
      bucket = { count: 0, resetTime: now + config.windowMs };
      store.set(key, bucket);
    }

    bucket.count += 1;
    const remaining = Math.max(0, config.max - bucket.count);
    const resetSeconds = Math.ceil((bucket.resetTime - now) / 1000);

    res.setHeader('RateLimit-Limit', config.max.toString());
    res.setHeader('RateLimit-Remaining', remaining.toString());
    res.setHeader('RateLimit-Reset', resetSeconds.toString());

    if (bucket.count > config.max) {
      res.setHeader('Retry-After', resetSeconds.toString());
      res.status(429).json({
        error: {
          code: 'RATE_LIMIT_EXCEEDED',
          message: 'Too many requests. Quota exceeded for this window.',
          retryAfterSeconds: resetSeconds,
        },
      });
      return;
    }

    next();
  };
}
```

### 3.3 Gateway App Composition (`src/app.ts`)
```typescript
import express, { Express } from 'express';
import { createCorsMiddleware, CorsConfig } from './middleware/cors';
import { createRateLimiter, RateLimitConfig } from './middleware/rateLimiter';

export interface GatewayConfig {
  cors: CorsConfig;
  rateLimit: RateLimitConfig;
}

export function createApp(config: GatewayConfig): Express {
  const app = express();

  // 1. CORS Preflight & Origin Header Inspection
  app.use(createCorsMiddleware(config.cors));

  // 2. Rate Limiting on Public Endpoints
  const rateLimiter = createRateLimiter(config.rateLimit);

  // Routes
  app.get('/public/health', rateLimiter, (_req, res) => {
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  });

  return app;
}
