### 1. Verification & Architectural Plan

#### Field Presence & Partial Patch Analysis
In the legacy REST endpoint, `status` can be `"ACTIVE"`, `"INACTIVE"`, or omitted/`null` for partial updates.
In Protobuf v3 (proto3):
- Proto3 primitive fields default to zero-values without presence tracking unless declared with the `optional` keyword (field presence) or coupled with a `google.protobuf.FieldMask`.
- To support partial PATCH semantics:
  - If using `optional string status = ...;` or `optional AccountStatus status = ...;`, generated Go code exposes a pointer (or `HasStatus()` / nil check).
  - Defensive error handling: Reject unmapped/invalid status strings with standard gRPC status code `codes.InvalidArgument`.

#### Migration Strategy
1. **Contract Mapping**:
   - Status mapping: `"ACTIVE"` $\rightarrow$ `ACCOUNT_STATUS_ACTIVE`, `"INACTIVE"` $\rightarrow$ `ACCOUNT_STATUS_INACTIVE`.
   - Distinguish `nil` / unset (do not update status) from invalid values.
2. **Defensive Validation**:
   - Validate account ID presence and format.
   - Return structured gRPC errors (`status.Error` / `status.Errorf` with `codes.InvalidArgument`, `codes.NotFound`).
3. **Layer Separation**:
   - `AccountServiceServer` handles transport, unmarshaling, proto-to-domain conversion, and error translation.
   - Domain repository/service handles the database persistence.

---

### 2. Implementation

Assuming standard Protobuf definition generated for Go:

```protobuf
// account_service.proto context
syntax = "proto3";
package account.v1;
option go_package = "github.com/example/service/gen/account/v1;accountv1";

enum AccountStatus {
  ACCOUNT_STATUS_UNSPECIFIED = 0;
  ACCOUNT_STATUS_ACTIVE = 1;
  ACCOUNT_STATUS_INACTIVE = 2;
}

message UpdateAccountRequest {
  string account_id = 1;
  optional AccountStatus status = 2;
  // alternative string representation if proto used optional string:
  // optional string status_str = 3;
}

message UpdateAccountResponse {
  Account account = 1;
}

message Account {
  string id = 1;
  AccountStatus status = 2;
}

service AccountService {
  rpc UpdateAccount(UpdateAccountRequest) returns (UpdateAccountResponse);
}
```

#### Go Service Implementation (`internal/service/account_service.go`)

```go
package service

import (
	"context"
	"errors"
	"strings"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	accountv1 "github.com/example/service/gen/account/v1"
)

// Domain repository/business interface
type AccountRepository interface {
	GetAccount(ctx context.Context, id string) (*DomainAccount, error)
	PatchAccount(ctx context.Context, id string, params PatchAccountParams) (*DomainAccount, error)
}

type DomainAccount struct {
	ID     string
	Status string // "ACTIVE", "INACTIVE"
}

type PatchAccountParams struct {
	// Status is nil if omitted (no update), or points to string if set
	Status *string
}

var (
	ErrAccountNotFound = errors.New("account not found")
)

// AccountServiceServer implements accountv1.AccountServiceServer
type AccountServiceServer struct {
	accountv1.UnimplementedAccountServiceServer
	repo AccountRepository
}

func NewAccountServiceServer(repo AccountRepository) *AccountServiceServer {
	return &AccountServiceServer{repo: repo}
}

// UpdateAccount handles partial patch updates preserving null/omitted semantics
func (s *AccountServiceServer) UpdateAccount(
	ctx context.Context,
	req *accountv1.UpdateAccountRequest,
) (*accountv1.UpdateAccountResponse, error) {
	if req == nil {
		return nil, status.Error(codes.InvalidArgument, "request cannot be nil")
	}

	accountID := strings.TrimSpace(req.GetAccountId())
	if accountID == "" {
		return nil, status.Error(codes.InvalidArgument, "account_id is required")
	}

	var patchParams PatchAccountParams

	// Proto3 optional presence check
	if req.Status != nil {
		protoStatus := req.GetStatus()
		switch protoStatus {
		case accountv1.AccountStatus_ACCOUNT_STATUS_ACTIVE:
			active := "ACTIVE"
			patchParams.Status = &active
		case accountv1.AccountStatus_ACCOUNT_STATUS_INACTIVE:
			inactive := "INACTIVE"
			patchParams.Status = &inactive
		case accountv1.AccountStatus_ACCOUNT_STATUS_UNSPECIFIED:
			return nil, status.Error(codes.InvalidArgument, "status cannot be ACCOUNT_STATUS_UNSPECIFIED when provided")
		default:
			return nil, status.Errorf(codes.InvalidArgument, "unsupported status enum value: %v", protoStatus)
		}
	}

	updated, err := s.repo.PatchAccount(ctx, accountID, patchParams)
	if err != nil {
		if errors.Is(err, ErrAccountNotFound) {
			return nil, status.Errorf(codes.NotFound, "account %q not found", accountID)
		}
		return nil, status.Errorf(codes.Internal, "failed to update account: %v", err)
	}

	protoStatus := mapDomainStatusToProto(updated.Status)

	return &accountv1.UpdateAccountResponse{
		Account: &accountv1.Account{
			Id:     updated.ID,
			Status: protoStatus,
		},
	}, nil
}

func mapDomainStatusToProto(statusStr string) accountv1.AccountStatus {
	switch strings.ToUpper(strings.TrimSpace(statusStr)) {
	case "ACTIVE":
		return accountv1.AccountStatus_ACCOUNT_STATUS_ACTIVE
	case "INACTIVE":
		return accountv1.AccountStatus_ACCOUNT_STATUS_INACTIVE
	default:
		return accountv1.AccountStatus_ACCOUNT_STATUS_UNSPECIFIED
	}
}
```

