### 4. Resolver Implementation (TypeScript 5.4)

#### `src/subgraphs/inventory/resolvers/product.resolver.ts`

```typescript
import { GraphQLError } from 'graphql';

export interface ProductKey {
  __typename: 'Product';
  id: string;
}

export interface InventoryItem {
  productId: string;
  priceInCents: number;
  quantityOnHand: number;
}

// Service layer interface adhering to layered architecture
export interface InventoryServiceDataSource {
  getInventoryItemByProductId(productId: string): Promise<InventoryItem | null>;
}

export interface ResolverContext {
  dataSources: {
    inventoryService: InventoryServiceDataSource;
  };
}

export const inventoryProductResolvers = {
  Product: {
    // Entity reference resolver for federated joins
    __resolveReference: async (
      reference: ProductKey,
      context: ResolverContext
    ): Promise<Partial<ProductKey> & { _inventoryItem?: InventoryItem | null }> => {
      if (!reference.id) {
        throw new GraphQLError('Entity reference missing required key: id', {
          extensions: { code: 'BAD_USER_INPUT' },
        });
      }

      try {
        const item = await context.dataSources.inventoryService.getInventoryItemByProductId(reference.id);
        return {
          id: reference.id,
          _inventoryItem: item,
        };
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : 'Unknown data source failure';
        throw new GraphQLError(`Failed resolving Product entity in InventoryService: ${message}`, {
          extensions: { code: 'INTERNAL_SERVER_ERROR', targetId: reference.id },
        });
      }
    },

    // Migrated "price" resolver (grounded in defensive error handling)
    price: async (
      parent: ProductKey & { _inventoryItem?: InventoryItem | null; price?: number },
      _args: unknown,
      context: ResolverContext
    ): Promise<number> => {
      // Re-use fetched entity if already cached in parent by __resolveReference
      if (parent._inventoryItem !== undefined) {
        if (!parent._inventoryItem) {
          throw new GraphQLError(`Pricing not found for product ID: ${parent.id}`, {
            extensions: { code: 'NOT_FOUND', productId: parent.id },
          });
        }
        return parent._inventoryItem.priceInCents;
      }

      try {
        const item = await context.dataSources.inventoryService.getInventoryItemByProductId(parent.id);
        if (!item) {
          throw new GraphQLError(`Pricing not found for product ID: ${parent.id}`, {
            extensions: { code: 'NOT_FOUND', productId: parent.id },
          });
        }
        return item.priceInCents;
      } catch (err: unknown) {
        if (err instanceof GraphQLError) throw err;
        const message = err instanceof Error ? err.message : 'Internal pricing lookup error';
        throw new GraphQLError(`Failed to resolve price: ${message}`, {
          extensions: { code: 'INTERNAL_SERVER_ERROR', productId: parent.id },
        });
      }
    },

    inStock: (
      parent: { _inventoryItem?: InventoryItem | null }
    ): boolean => {
      return (parent._inventoryItem?.quantityOnHand ?? 0) > 0;
    },

    inventoryCount: (
      parent: { _inventoryItem?: InventoryItem | null }
    ): number => {
      return parent._inventoryItem?.quantityOnHand ?? 0;
    },
  },
};
```

