### 1. Architectural & Idempotency Strategy

To handle **duplicate events** and **out-of-order retries** safely under Go 1.22 and our layered service architecture:

1. **Deduplication Boundary**:
   - Every event has a unique `event_id`.
   - Process events inside a single database transaction that inserts into a `processed_events (event_id, processed_at)` table (`ON CONFLICT DO NOTHING`). If 0 rows are affected, it is a duplicate and is safely skipped.
2. **Out-of-Order Handling**:
   - The entity row tracks a monotonic sequence/version (e.g. `version` or `event_timestamp`).
   - Mutations use optimistic concurrency checks:
     ```sql
     UPDATE payments 
     SET status = 'RECEIVED', amount = $1, version = $2, updated_at = NOW()
     WHERE payment_id = $3 AND version < $2;
     ```
   - If the event is older than the current persisted version, the state mutation is skipped, but the transaction still succeeds so the Kafka offset can commit.
3. **Offset Management**:
   - Offsets are committed manually **only after** the database transaction successfully commits.

---

### 2. Implementation (`Go 1.22`)

```go
package consumer

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/segmentio/kafka-go"
)

var (
	ErrDuplicateEvent = errors.New("duplicate event detected")
	ErrStaleEvent     = errors.New("stale event version ignored")
)

// PaymentReceivedEvent defines the data contract for payment ingestion.
type PaymentReceivedEvent struct {
	EventID    string    `json:"event_id"`
	PaymentID  string    `json:"payment_id"`
	Amount     int64     `json:"amount_cents"`
	Currency   string    `json:"currency"`
	Version    int64     `json:"version"`
	OccurredAt time.Time `json:"occurred_at"`
}

type PaymentRepository interface {
	ApplyPaymentReceived(ctx context.Context, evt PaymentReceivedEvent) error
}

type PostgresPaymentRepository struct {
	db *sql.DB
}

func NewPostgresPaymentRepository(db *sql.DB) *PostgresPaymentRepository {
	return &PostgresPaymentRepository{db: db}
}

// ApplyPaymentReceived atomically registers the event and applies state changes idempotently.
func (r *PostgresPaymentRepository) ApplyPaymentReceived(ctx context.Context, evt PaymentReceivedEvent) error {
	tx, err := r.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelReadCommitted})
	if err != nil {
		return fmt.Errorf("failed to begin tx: %w", err)
	}
	defer tx.Rollback()

	// 1. Idempotency Check: Deduplicate via processed_events table
	dedupQuery := `
		INSERT INTO processed_events (event_id, payment_id, processed_at)
		VALUES ($1, $2, NOW())
		ON CONFLICT (event_id) DO NOTHING;
	`
	res, err := tx.ExecContext(ctx, dedupQuery, evt.EventID, evt.PaymentID)
	if err != nil {
		return fmt.Errorf("failed to record event idempotency: %w", err)
	}

	rowsAffected, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to read affected rows: %w", err)
	}
	if rowsAffected == 0 {
		// Event was already processed; exit early and commit offset.
		return ErrDuplicateEvent
	}

	// 2. Out-of-Order Check: Ensure monotonic version sequencing
	updateQuery := `
		INSERT INTO payments (payment_id, status, amount_cents, currency, version, updated_at)
		VALUES ($1, 'RECEIVED', $2, $3, $4, NOW())
		ON CONFLICT (payment_id) DO UPDATE
		SET status = 'RECEIVED',
		    amount_cents = EXCLUDED.amount_cents,
		    currency = EXCLUDED.currency,
		    version = EXCLUDED.version,
		    updated_at = NOW()
		WHERE payments.version < EXCLUDED.version;
	`
	res, err = tx.ExecContext(ctx, updateQuery, evt.PaymentID, evt.Amount, evt.Currency, evt.Version)
	if err != nil {
		return fmt.Errorf("failed to upsert payment status: %w", err)
	}

	stateRows, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to inspect state update count: %w", err)
	}
	if stateRows == 0 {
		slog.WarnContext(ctx, "received stale or out-of-order payment event; skipped state modification",
			slog.String("payment_id", evt.PaymentID),
			slog.Int64("event_version", evt.Version),
		)
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("failed to commit payment update tx: %w", err)
	}

	return nil
}

type PaymentEventConsumer struct {
	reader *kafka.Reader
	repo   PaymentRepository
	logger *slog.Logger
}

func NewPaymentEventConsumer(reader *kafka.Reader, repo PaymentRepository, logger *slog.Logger) *PaymentEventConsumer {
	return &PaymentEventConsumer{
		reader: reader,
		repo:   repo,
		logger: logger,
	}
}

// Run executes the consumer read loop with defensive retry and offset management.
func (c *PaymentEventConsumer) Run(ctx context.Context) error {
	c.logger.Info("starting PaymentReceivedEvent consumer loop")

	for {
		msg, err := c.reader.FetchMessage(ctx)
		if err != nil {
			if errors.Is(err, context.Canceled) {
				c.logger.Info("consumer loop context cancelled; shutting down")
				return nil
			}
			c.logger.Error("fetch error from kafka broker", slog.String("error", err.Error()))
			return err
		}

		var event PaymentReceivedEvent
		if err := json.Unmarshal(msg.Value, &event); err != nil {
			c.logger.Error("malformed event payload; committing offset to avoid poison pill",
				slog.Int64("offset", msg.Offset),
				slog.String("error", err.Error()),
			)
			_ = c.reader.CommitMessages(ctx, msg)
			continue
		}

		err = c.repo.ApplyPaymentReceived(ctx, event)
		if err != nil && !errors.Is(err, ErrDuplicateEvent) {
			c.logger.Error("transient database processing error, backing off before retry",
				slog.String("event_id", event.EventID),
				slog.String("payment_id", event.PaymentID),
				slog.String("error", err.Error()),
			)
			// Backoff and do not commit offset to allow Kafka retry
			time.Sleep(500 * time.Millisecond)
			continue
		}

		if errors.Is(err, ErrDuplicateEvent) {
			c.logger.Info("duplicate event ignored",
				slog.String("event_id", event.EventID),
				slog.String("payment_id", event.PaymentID),
			)
		}

		// Explicit manual offset commit after successful persistence or duplicate detection
		if commitErr := c.reader.CommitMessages(ctx, msg); commitErr != nil {
			c.logger.Error("failed to commit message offset",
				slog.Int64("offset", msg.Offset),
				slog.String("error", commitErr.Error()),
			)
		}
	}
}
```

