### 2. Implementation: Ingress Auth Middleware (Go 1.22)

```go
package middleware

import (
	"encoding/json"
	"net/http"
	"strings"
)

// StructuredError matches systemPatterns.md defensive structured error standard.
type StructuredError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

type ErrorResponse struct {
	Error StructuredError `json:"error"`
}

func writeJSONError(w http.ResponseWriter, status int, code, message string) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(ErrorResponse{
		Error: StructuredError{
			Code:    code,
			Message: message,
		},
	})
}

// RequireOAuth2BearerMiddleware enforces OAuth2 Bearer tokens and rejects legacy X-API-Key headers.
func RequireOAuth2BearerMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// 1. Explicitly reject legacy X-API-Key
		if r.Header.Get("X-API-Key") != "" {
			writeJSONError(
				w,
				http.StatusUnauthorized,
				"AUTH_LEGACY_KEY_DEPRECATED",
				"X-API-Key is deprecated in API v2. Please use OAuth2 Bearer authentication.",
			)
			return
		}

		// 2. Validate Authorization header format
		authHeader := r.Header.Get("Authorization")
		if authHeader == "" {
			writeJSONError(
				w,
				http.StatusUnauthorized,
				"AUTH_TOKEN_REQUIRED",
				"Authorization header missing. Expected 'Authorization: Bearer <token>'.",
			)
			return
		}

		parts := strings.SplitN(authHeader, " ", 2)
		if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") || strings.TrimSpace(parts[1]) == "" {
			writeJSONError(
				w,
				http.StatusUnauthorized,
				"AUTH_TOKEN_MALFORMED",
				"Invalid Authorization header format. Expected 'Bearer <token>'.",
			)
			return
		}

		token := strings.TrimSpace(parts[1])

		// Attach extracted token to request context for downstream verification
		ctx := WithToken(r.Context(), token)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}
```

