### 2. Client Pattern & Implementation Scaffold

In accordance with TypeScript 5.4 and structured error handling (`systemPatterns.md`), here is the client architecture to which the generated endpoints will bind:

```typescript
// src/api/client.ts

export interface ApiErrorPayload {
  code: string;
  message: string;
  details?: Record<string, unknown>;
}

export class ApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly error: ApiErrorPayload
  ) {
    super(`[${error.code}] ${error.message}`);
    this.name = 'ApiError';
  }
}

export interface ClientConfig {
  baseUrl: string;
  getAuthToken?: () => Promise<string | null> | string | null;
}

export class ApiClient {
  constructor(private config: ClientConfig) {}

  private async request<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<T> {
    const url = `${this.config.baseUrl.replace(/\/$/, '')}/${endpoint.replace(/^\//, '')}`;
    const headers = new Headers(options.headers);
    headers.set('Content-Type', 'application/json');

    if (this.config.getAuthToken) {
      const token = await this.config.getAuthToken();
      if (token) {
        headers.set('Authorization', `Bearer ${token}`);
      }
    }

    const response = await fetch(url, { ...options, headers });

    if (!response.ok) {
      let errorPayload: ApiErrorPayload;
      try {
        errorPayload = await response.json();
      } catch {
        errorPayload = {
          code: 'UNKNOWN_ERROR',
          message: response.statusText || 'An unexpected error occurred',
        };
      }
      throw new ApiError(response.status, errorPayload);
    }

    if (response.status === 204) {
      return undefined as unknown as T;
    }

    return response.json() as Promise<T>;
  }

  // Endpoint stubs will be generated here once openapi.yaml definitions are supplied
}
```

