Continuing with the **WalletTransferService** track, here is the concrete specification and implementation plan incorporating the deterministic lock ordering pattern, defensive error handling, and transactional boundaries.

---

### 1. Concrete Service Implementation (`internal/service/wallet.go`)

This service layer encapsulates the transactional boundary, lock ordering, balance assertions, and double-entry ledger writes:

```go
package service

import (
	"bytes"
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	walletv1 "github.com/org/repo/gen/wallet/v1"
)

var (
	ErrSameAccount          = status.Error(codes.InvalidArgument, "source and destination accounts must differ")
	ErrInvalidAmount        = status.Error(codes.InvalidArgument, "transfer amount must be strictly positive")
	ErrCurrencyMismatch     = status.Error(codes.InvalidArgument, "account currencies must match transfer currency")
	ErrInsufficientFunds    = status.Error(codes.FailedPrecondition, "insufficient balance for transfer")
	ErrAccountFrozen        = status.Error(codes.FailedPrecondition, "one or more accounts are locked/frozen")
	ErrAccountNotFound      = status.Error(codes.NotFound, "one or more accounts do not exist")
	ErrIdempotencyConflict  = status.Error(codes.AlreadyExists, "idempotency key reused with mismatched parameters")
)

type Account struct {
	ID           uuid.UUID
	UserID       uuid.UUID
	Currency     string
	BalanceCents int64
	Locked       bool
}

type WalletRepository interface {
	WithTx(ctx context.Context, fn func(tx *sql.Tx) error) error
	GetTransferByIdempotencyKey(ctx context.Context, tx *sql.Tx, key string) (*walletv1.TransferFundsResponse, error)
	LockAccountsDeterministic(ctx context.Context, tx *sql.Tx, idA, idB uuid.UUID) (map[uuid.UUID]*Account, error)
	ApplyLedgerTransfer(ctx context.Context, tx *sql.Tx, transferID uuid.UUID, key string, src, dst *Account, amount int64, narration string) (*walletv1.TransferFundsResponse, error)
}

type WalletTransferService struct {
	walletv1.UnimplementedWalletTransferServiceServer
	repo WalletRepository
}

func NewWalletTransferService(repo WalletRepository) *WalletTransferService {
	return &WalletTransferService{repo: repo}
}

func (s *WalletTransferService) TransferFunds(
	ctx context.Context,
	req *walletv1.TransferFundsRequest,
) (*walletv1.TransferFundsResponse, error) {
	// 1. Validation
	if req.GetIdempotencyKey() == "" {
		return nil, status.Error(codes.InvalidArgument, "idempotency_key is required")
	}
	if req.GetAmount().GetAmountCents() <= 0 {
		return nil, ErrInvalidAmount
	}

	srcID, err := uuid.Parse(req.GetSourceAccountId())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid source_account_id")
	}

	dstID, err := uuid.Parse(req.GetDestinationAccountId())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid destination_account_id")
	}

	if srcID == dstID {
		return nil, ErrSameAccount
	}

	amountCents := req.GetAmount().GetAmountCents()
	currency := req.GetAmount().GetCurrency()

	var resp *walletv1.TransferFundsResponse

	// 2. Transaction Boundary
	err = s.repo.WithTx(ctx, func(tx *sql.Tx) error {
		// 2a. Idempotency Check
		existing, err := s.repo.GetTransferByIdempotencyKey(ctx, tx, req.GetIdempotencyKey())
		if err == nil && existing != nil {
			resp = existing
			return nil
		}
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return fmt.Errorf("failed to check idempotency key: %w", err)
		}

		// 2b. Deterministic Lock Acquisition (deadlock prevention)
		accounts, err := s.repo.LockAccountsDeterministic(ctx, tx, srcID, dstID)
		if err != nil {
			return err
		}

		srcAcc, okSrc := accounts[srcID]
		dstAcc, okDst := accounts[dstID]
		if !okSrc || !okDst {
			return ErrAccountNotFound
		}

		// 2c. Business Invariant Checks
		if srcAcc.Locked || dstAcc.Locked {
			return ErrAccountFrozen
		}
		if srcAcc.Currency != currency || dstAcc.Currency != currency {
			return ErrCurrencyMismatch
		}
		if srcAcc.BalanceCents < amountCents {
			return ErrInsufficientFunds
		}

		// 2d. Apply State Changes (Debit, Credit, Ledger Entries, Transfer Record)
		transferID := uuid.New()
		resp, err = s.repo.ApplyLedgerTransfer(ctx, tx, transferID, req.GetIdempotencyKey(), srcAcc, dstAcc, amountCents, req.GetNarration())
		return err
	})

	if err != nil {
		return nil, err
	}

	return resp, nil
}
