To support **Redis Sentinel (dev/failover)** and **Redis Cluster (prod)** without leaking infrastructure details into your domain logic, we should apply two patterns:

1. **Interface Decoupling via `redis.Cmdable`**: The `RedisSessionStore` should only depend on the standard command interface (`redis.Cmdable` from `go-redis/v9`), making it agnostic to whether it is speaking to a single node, Sentinel failover client, or Cluster client.
2. **Topology-Aware Factory / Universal Client**: Use a configuration-driven connection factory.

---

### 1. Connection Topology Architecture

`go-redis/v9` provides `redis.UniversalClient`, which can be configured directly or wrapped in a custom factory to provide explicit validation per topology mode.

#### Unified Configuration Schema

```go
type RedisTopology string

const (
    TopologyStandalone RedisTopology = "standalone"
    TopologySentinel   RedisTopology = "sentinel"
    TopologyCluster    RedisTopology = "cluster"
)

type RedisConfig struct {
    Topology     RedisTopology `yaml:"topology" env:"REDIS_TOPOLOGY"`
    Addresses    []string      `yaml:"addresses" env:"REDIS_ADDRESSES"`       // Sentinel addrs or Cluster seed nodes
    MasterName   string        `yaml:"master_name" env:"REDIS_MASTER_NAME"`   // Required for Sentinel
    Username     string        `yaml:"username" env:"REDIS_USERNAME"`
    Password     string        `yaml:"password" env:"REDIS_PASSWORD"`
    DB           int           `yaml:"db" env:"REDIS_DB"`                     // Note: Cluster only supports DB 0

    // Pool & Timeout Configuration
    PoolSize     int           `yaml:"pool_size" env:"REDIS_POOL_SIZE"`
    MinIdleConns int           `yaml:"min_idle_conns" env:"REDIS_MIN_IDLE_CONNS"`
    DialTimeout  time.Duration `yaml:"dial_timeout" env:"REDIS_DIAL_TIMEOUT"`
    ReadTimeout  time.Duration `yaml:"read_timeout" env:"REDIS_READ_TIMEOUT"`
    WriteTimeout time.Duration `yaml:"write_timeout" env:"REDIS_WRITE_TIMEOUT"`

    // Cluster-specific tuning
    RouteByLatency bool        `yaml:"route_by_latency"`
}
```

#### Factory Initialization

```go
package cache

import (
    "context"
    "fmt"
    "github.com/redis/go-redis/v9"
)

func NewRedisClient(cfg RedisConfig) (redis.UniversalClient, error) {
    switch cfg.Topology {
    case TopologySentinel:
        if cfg.MasterName == "" {
            return nil, fmt.Errorf("redis sentinel requires master_name")
        }
        return redis.NewFailoverClient(&redis.FailoverOptions{
            MasterName:    cfg.MasterName,
            SentinelAddrs: cfg.Addresses,
            Password:      cfg.Password,
            DB:            cfg.DB,
            PoolSize:      cfg.PoolSize,
            MinIdleConns:  cfg.MinIdleConns,
            DialTimeout:   cfg.DialTimeout,
            ReadTimeout:   cfg.ReadTimeout,
            WriteTimeout:  cfg.WriteTimeout,
        }), nil

    case TopologyCluster:
        if cfg.DB != 0 {
            return nil, fmt.Errorf("redis cluster only supports DB 0")
        }
        return redis.NewClusterClient(&redis.ClusterOptions{
            Addrs:          cfg.Addresses,
            Password:       cfg.Password,
            PoolSize:       cfg.PoolSize,
            MinIdleConns:   cfg.MinIdleConns,
            DialTimeout:    cfg.DialTimeout,
            ReadTimeout:    cfg.ReadTimeout,
            WriteTimeout:   cfg.WriteTimeout,
            RouteByLatency: cfg.RouteByLatency,
        }), nil

    case TopologyStandalone:
        return redis.NewClient(&redis.Options{
            Addr:         cfg.Addresses[0],
            Password:     cfg.Password,
            DB:           cfg.DB,
            PoolSize:     cfg.PoolSize,
            MinIdleConns: cfg.MinIdleConns,
            DialTimeout:  cfg.DialTimeout,
            ReadTimeout:  cfg.ReadTimeout,
            WriteTimeout: cfg.WriteTimeout,
        }), nil

    default:
        return nil, fmt.Errorf("unsupported redis topology: %s", cfg.Topology)
    }
}
```

