#### 2. Rate-Limiting Headers Middleware (`internal/gateway/middleware/ratelimit.go`)

```go
package middleware

import (
	"context"
	"net/http"
	"strconv"
	"time"
)

// RateLimiter defines the interface for token-bucket or sliding-window rate limit evaluation.
type RateLimiter interface {
	// Allow checks if the request key is permitted and returns limit metadata.
	Allow(ctx context.Context, key string) (RateLimitResult, error)
}

// RateLimitResult contains metadata required for standard client response headers.
type RateLimitResult struct {
	Allowed   bool
	Limit     int64
	Remaining int64
	ResetAt   time.Time
}

// RateLimitConfig configures rate-limiting header injection and quota enforcement.
type RateLimitConfig struct {
	Limiter    RateLimiter
	KeyExtract func(r *http.Request) string
}

// RateLimitMiddleware enforces limits and attaches standard rate-limiting headers.
func RateLimitMiddleware(cfg RateLimitConfig) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			key := cfg.KeyExtract(r)
			res, err := cfg.Limiter.Allow(r.Context(), key)
			if err != nil {
				// Fail open or closed depending on policy; log defensively
				http.Error(w, `{"code":"INTERNAL","message":"Rate limit check unavailable"}`, http.StatusInternalServerError)
				return
			}

			now := time.Now()
			resetSeconds := int64(res.ResetAt.Sub(now).Seconds())
			if resetSeconds < 0 {
				resetSeconds = 0
			}

			// Dual compatibility: standard draft-ietf headers and classic X-* headers
			limitStr := strconv.FormatInt(res.Limit, 10)
			remainingStr := strconv.FormatInt(res.Remaining, 10)
			resetSecStr := strconv.FormatInt(resetSeconds, 10)
			resetEpochStr := strconv.FormatInt(res.ResetAt.Unix(), 10)

			// RFC / IETF Draft format
			w.Header().Set("RateLimit-Limit", limitStr)
			w.Header().Set("RateLimit-Remaining", remainingStr)
			w.Header().Set("RateLimit-Reset", resetSecStr)

			// De-facto industry standard headers
			w.Header().Set("X-RateLimit-Limit", limitStr)
			w.Header().Set("X-RateLimit-Remaining", remainingStr)
			w.Header().Set("X-RateLimit-Reset", resetEpochStr)

			if !res.Allowed {
				w.Header().Set("Retry-After", resetSecStr)
				w.Header().Set("Content-Type", "application/json; charset=utf-8")
				w.WriteHeader(http.StatusTooManyRequests)
				_, _ = w.Write([]byte(`{"code":"RESOURCE_EXHAUSTED","message":"Too many requests. Quota exceeded."}`))
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}
```

