### Step 1: CORS Middleware Implementation

```go
// internal/gateway/middleware/cors.go
package middleware

import (
	"net/http"
	"net/url"
	"strconv"
	"strings"
)

// CORSConfig holds exact configuration parameters for CORS handling.
type CORSConfig struct {
	// AllowedOrigins contains exact origin strings, e.g., "https://app.example.com".
	// Wildcard "*" is supported ONLY when AllowCredentials is false.
	AllowedOrigins   []string
	AllowedMethods   []string
	AllowedHeaders   []string
	ExposedHeaders   []string
	AllowCredentials bool
	MaxAgeSeconds    int
}

// CanonicalizeOrigin parses an origin string and normalizes it to scheme://host[:port].
func CanonicalizeOrigin(raw string) (string, bool) {
	raw = strings.TrimSpace(raw)
	if raw == "*" {
		return "*", true
	}

	u, err := url.Parse(raw)
	if err != nil || u.Scheme == "" || u.Host == "" || u.Path != "" || u.RawQuery != "" {
		return "", false
	}

	scheme := strings.ToLower(u.Scheme)
	if scheme != "http" && scheme != "https" {
		return "", false
	}

	return scheme + "://" + strings.ToLower(u.Host), true
}

// CORS constructs an HTTP middleware enforcing strict CORS rules.
func CORS(cfg CORSConfig) func(http.Handler) http.Handler {
	allowedOriginSet := make(map[string]struct{}, len(cfg.AllowedOrigins))
	wildcardAllowed := false

	for _, raw := range cfg.AllowedOrigins {
		canonical, ok := CanonicalizeOrigin(raw)
		if !ok {
			continue
		}
		if canonical == "*" {
			wildcardAllowed = true
		} else {
			allowedOriginSet[canonical] = struct{}{}
		}
	}

	allowedMethodsStr := strings.Join(cfg.AllowedMethods, ", ")
	allowedHeadersStr := strings.Join(cfg.AllowedHeaders, ", ")
	exposedHeadersStr := strings.Join(cfg.ExposedHeaders, ", ")
	maxAgeStr := strconv.Itoa(cfg.MaxAgeSeconds)

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			rawOrigin := r.Header.Get("Origin")
			if rawOrigin == "" {
				next.ServeHTTP(w, r)
				return
			}

			originCanonical, ok := CanonicalizeOrigin(rawOrigin)
			if !ok {
				// Malformed origin: skip CORS headers and proceed or reject
				next.ServeHTTP(w, r)
				return
			}

			originAllowed := false
			matchedHeaderValue := ""

			if wildcardAllowed && !cfg.AllowCredentials {
				originAllowed = true
				matchedHeaderValue = "*"
			} else if _, exists := allowedOriginSet[originCanonical]; exists {
				originAllowed = true
				matchedHeaderValue = rawOrigin
			}

			if !originAllowed {
				// Disallowed origin: do not attach CORS response headers
				if r.Method == http.MethodOptions && r.Header.Get("Access-Control-Request-Method") != "" {
					w.WriteHeader(http.StatusForbidden)
					return
				}
				next.ServeHTTP(w, r)
				return
			}

			// Apply CORS headers for authorized origins
			w.Header().Set("Access-Control-Allow-Origin", matchedHeaderValue)
			w.Header().Add("Vary", "Origin")

			if cfg.AllowCredentials {
				w.Header().Set("Access-Control-Allow-Credentials", "true")
			}

			if len(cfg.ExposedHeaders) > 0 {
				w.Header().Set("Access-Control-Expose-Headers", exposedHeadersStr)
			}

			// Preflight OPTIONS handling
			if r.Method == http.MethodOptions && r.Header.Get("Access-Control-Request-Method") != "" {
				w.Header().Add("Vary", "Access-Control-Request-Method")
				w.Header().Add("Vary", "Access-Control-Request-Headers")

				if allowedMethodsStr != "" {
					w.Header().Set("Access-Control-Allow-Methods", allowedMethodsStr)
				}
				if allowedHeadersStr != "" {
					w.Header().Set("Access-Control-Allow-Headers", allowedHeadersStr)
				}
				if cfg.MaxAgeSeconds > 0 {
					w.Header().Set("Access-Control-Max-Age", maxAgeStr)
				}

				w.WriteHeader(http.StatusNoContent)
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}
