### Step 2: Rate-Limiting Headers Middleware Implementation

```go
// internal/gateway/middleware/ratelimit.go
package middleware

import (
	"context"
	"encoding/json"
	"net"
	"net/http"
	"strconv"
	"strings"
	"time"
)

// RateLimiter defines the contract for rate-limit evaluation.
type RateLimiter interface {
	Allow(ctx context.Context, key string) (RateLimitResult, error)
}

// RateLimitResult contains quota status details.
type RateLimitResult struct {
	Allowed   bool
	Limit     int64
	Remaining int64
	ResetAt   time.Time
}

// RateLimitConfig configures the rate-limiting middleware.
type RateLimitConfig struct {
	Limiter    RateLimiter
	KeyExtract func(r *http.Request) string
}

// DefaultIPKeyExtractor extracts client IP from RemoteAddr or trusted X-Forwarded-For.
func DefaultIPKeyExtractor(r *http.Request) string {
	xff := r.Header.Get("X-Forwarded-For")
	if xff != "" {
		parts := strings.Split(xff, ",")
		clientIP := strings.TrimSpace(parts[0])
		if clientIP != "" {
			return clientIP
		}
	}
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err == nil {
		return host
	}
	return r.RemoteAddr
}

type errorEnvelope struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// RateLimit returns an http.Handler middleware that applies rate limit headers and gates requests.
func RateLimit(cfg RateLimitConfig) func(http.Handler) http.Handler {
	if cfg.KeyExtract == nil {
		cfg.KeyExtract = DefaultIPKeyExtractor
	}

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			key := cfg.KeyExtract(r)
			res, err := cfg.Limiter.Allow(r.Context(), key)
			if err != nil {
				w.Header().Set("Content-Type", "application/json; charset=utf-8")
				w.WriteHeader(http.StatusInternalServerError)
				_ = json.NewEncoder(w).Encode(errorEnvelope{
					Code:    "INTERNAL",
					Message: "Rate limiter service unavailable",
				})
				return
			}

			now := time.Now()
			resetSeconds := int64(res.ResetAt.Sub(now).Seconds())
			if resetSeconds < 0 {
				resetSeconds = 0
			}

			limitStr := strconv.FormatInt(res.Limit, 10)
			remainingStr := strconv.FormatInt(res.Remaining, 10)
			resetSecStr := strconv.FormatInt(resetSeconds, 10)
			resetEpochStr := strconv.FormatInt(res.ResetAt.Unix(), 10)

			// IETF draft headers
			w.Header().Set("RateLimit-Limit", limitStr)
			w.Header().Set("RateLimit-Remaining", remainingStr)
			w.Header().Set("RateLimit-Reset", resetSecStr)

			// Legacy standard headers
			w.Header().Set("X-RateLimit-Limit", limitStr)
			w.Header().Set("X-RateLimit-Remaining", remainingStr)
			w.Header().Set("X-RateLimit-Reset", resetEpochStr)

			if !res.Allowed {
				w.Header().Set("Retry-After", resetSecStr)
				w.Header().Set("Content-Type", "application/json; charset=utf-8")
				w.WriteHeader(http.StatusTooManyRequests)
				_ = json.NewEncoder(w).Encode(errorEnvelope{
					Code:    "RESOURCE_EXHAUSTED",
					Message: "Quota exceeded. Too many requests.",
				})
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}
