// internal/gateway/middleware/middleware_test.go
package middleware_test

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"internal/gateway/middleware"
)

type mockLimiter struct {
	allowed   bool
	limit     int64
	remaining int64
	resetAt   time.Time
	err       error
}

func (m *mockLimiter) Allow(_ context.Context, _ string) (middleware.RateLimitResult, error) {
	return middleware.RateLimitResult{
		Allowed:   m.allowed,
		Limit:     m.limit,
		Remaining: m.remaining,
		ResetAt:   m.resetAt,
	}, m.err
}

func TestCORS_StrictAllowlist(t *testing.T) {
	cfg := middleware.CORSConfig{
		AllowedOrigins: []string{
			"https://app.example.com",
			"https://admin.example.com:8443",
		},
		AllowedMethods:   []string{"GET", "POST"},
		AllowedHeaders:   []string{"Authorization", "Content-Type"},
		ExposedHeaders:   []string{"X-Request-ID"},
		AllowCredentials: true,
		MaxAgeSeconds:    600,
	}

	handler := middleware.CORS(cfg)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))

	tests := []struct {
		name           string
		origin         string
		method         string
		preflight      bool
		wantStatus     int
		wantAllowOrig  string
		wantAllowCreds string
	}{
		{
			name:           "Valid whitelisted origin",
			origin:         "https://app.example.com",
			method:         "GET",
			wantStatus:     http.StatusOK,
			wantAllowOrig:  "https://app.example.com",
			wantAllowCreds: "true",
		},
		{
			name:           "Attacker subdomain takeover / bypass attempt",
			origin:         "https://evil.example.com",
			method:         "GET",
			wantStatus:     http.StatusOK,
			wantAllowOrig:  "",
			wantAllowCreds: "",
		},
		{
			name:           "Prefix collision attempt",
			origin:         "https://app.example.com.attacker.com",
			method:         "GET",
			wantStatus:     http.StatusOK,
			wantAllowOrig:  "",
			wantAllowCreds: "",
		},
		{
			name:           "Valid preflight OPTIONS",
			origin:         "https://app.example.com",
			method:         "OPTIONS",
			preflight:      true,
			wantStatus:     http.StatusNoContent,
			wantAllowOrig:  "https://app.example.com",
			wantAllowCreds: "true",
		},
		{
			name:       "Unauthorized origin preflight",
			origin:     "https://rogue.example.com",
			method:     "OPTIONS",
			preflight:  true,
			wantStatus: http.StatusForbidden,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := httptest.NewRequest(tt.method, "/v1/users", nil)
			if tt.origin != "" {
				req.Header.Set("Origin", tt.origin)
			}
			if tt.preflight {
				req.Header.Set("Access-Control-Request-Method", "POST")
			}

			rec := httptest.NewRecorder()
			handler.ServeHTTP(rec, req)

			if rec.Code != tt.wantStatus {
				t.Errorf("status code = %d, want %d", rec.Code, tt.wantStatus)
			}
			if got := rec.Header().Get("Access-Control-Allow-Origin"); got != tt.wantAllowOrig {
				t.Errorf("Access-Control-Allow-Origin = %q, want %q", got, tt.wantAllowOrig)
			}
			if got := rec.Header().Get("Access-Control-Allow-Credentials"); got != tt.wantAllowCreds {
				t.Errorf("Access-Control-Allow-Credentials = %q, want %q", got, tt.wantAllowCreds)
			}
		})
	}
}

func TestRateLimit_HeadersAndQuotaExhaustion(t *testing.T) {
	resetTime := time.Now().Add(30 * time.Second)

	limiter := &mockLimiter{
		allowed:   true,
		limit:     100,
		remaining: 99,
		resetAt:   resetTime,
	}

	cfg := middleware.RateLimitConfig{
		Limiter: limiter,
		KeyExtract: func(r *http.Request) string {
			return "user:123"
		},
	}

	handler := middleware.RateLimit(cfg)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))

	// Case 1: Permitted request
	req := httptest.NewRequest("GET", "/v1/data", nil)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", rec.Code)
	}
	if rec.Header().Get("RateLimit-Limit") != "100" {
		t.Errorf("RateLimit-Limit = %q, want 100", rec.Header().Get("RateLimit-Limit"))
	}
	if rec.Header().Get("RateLimit-Remaining") != "99" {
		t.Errorf("RateLimit-Remaining = %q, want 99", rec.Header().Get("RateLimit-Remaining"))
	}
	if rec.Header().Get("X-RateLimit-Limit") != "100" {
		t.Errorf("X-RateLimit-Limit = %q, want 100", rec.Header().Get("X-RateLimit-Limit"))
	}

	// Case 2: Exhausted quota
	limiter.allowed = false
	limiter.remaining = 0

	recExhausted := httptest.NewRecorder()
	handler.ServeHTTP(recExhausted, req)

	if recExhausted.Code != http.StatusTooManyRequests {
		t.Fatalf("expected 429, got %d", recExhausted.Code)
	}
	if recExhausted.Header().Get("Retry-After") == "" {
		t.Error("expected Retry-After header to be present")
	}
	if recExhausted.Header().Get("RateLimit-Remaining") != "0" {
		t.Errorf("RateLimit-Remaining = %q, want 0", recExhausted.Header().Get("RateLimit-Remaining"))
	}
}
