import React from 'react';

export interface NotificationItem {
  id: string;
  message: string;
  timestamp: string | number | Date;
  read?: boolean;
}

interface NotificationsListProps {
  notifications: NotificationItem[];
  onClearAll: () => void;
}

export const NotificationsList: React.FC<NotificationsListProps> = ({
  notifications,
  onClearAll,
}) => {
  // Sort descending by timestamp (newest first)
  const sortedNotifications = [...notifications].sort((a, b) => {
    const timeA = new Date(a.timestamp).getTime();
    const timeB = new Date(b.timestamp).getTime();
    return timeB - timeA;
  });

  return (
    <div className="notifications-list">
      <div className="notifications-header">
        <h2>Notifications</h2>
        <button
          type="button"
          data-testid="clear-all-btn"
          onClick={onClearAll}
        >
          Clear All
        </button>
      </div>

      <ul>
        {sortedNotifications.map((notification) => (
          <li key={notification.id}>
            <span>{notification.message}</span>
            <time dateTime={new Date(notification.timestamp).toISOString()}>
              {new Date(notification.timestamp).toLocaleString()}
            </time>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default NotificationsList;
```

#### Key Changes in `NotificationsList.tsx`:
- **Inverted Sort Order:** Changed comparison from ascending (`timeA - timeB`) to descending (`timeB - timeA`).
- **Clear Button Attribute:** Added `data-testid="clear-all-btn"` to the clear button.

